import {
  colors,
  durationMs,
  easings,
  font,
  px,
  scale,
  shadowLayerCss,
  shadows,
} from "./model.mjs";

const HEADER = `/**
 * Houston design tokens — typed constants for TypeScript surfaces (SDK, web).
 * AUTO-GENERATED by @houston/design-tokens. Do NOT edit by hand.
 * Rebuild: pnpm --filter @houston/design-tokens build
 */`;

// A bare object literal (no `as const`), so it can be a top-level export value
// or nested inside `color`. Indent controls nesting depth.
const lit = (entries, indent = "  ") =>
  `{\n${entries.map(([k, v]) => `${indent}${JSON.stringify(k)}: ${v},`).join("\n")}\n${indent.slice(2)}}`;

const strLit = (entries, indent) =>
  lit(
    entries.map(({ name, value }) => [name, JSON.stringify(value)]),
    indent,
  );

/** One theme's elevation tiers, each as a single box-shadow string. */
const boxShadows = (tokens, indent) =>
  strLit(
    shadows(tokens).map(({ name, layers }) => ({
      name,
      value: layers.map(shadowLayerCss).join(", "),
    })),
    indent,
  );

/**
 * The palette library as the picker reads it: ordered, named, and carrying four
 * resolved hexes per palette so a swatch needs no CSS-variable lookup.
 */
const paletteList = (palettes) =>
  `[\n${palettes
    .map((p) =>
      [
        "  {",
        `    id: ${JSON.stringify(p.id)},`,
        `    name: ${JSON.stringify(p.name)},`,
        `    mode: ${JSON.stringify(p.mode)},`,
        `    swatch: ${strLit(
          Object.entries(p.swatch).map(([name, value]) => ({ name, value })),
          "      ",
        )},`,
        "  },",
      ].join("\n"),
    )
    .join("\n")}\n]`;

export function buildTs(light, dark, palettes) {
  const durations = scale(light, "duration");
  const parts = [
    HEADER,
    "",
    'export type ThemeName = "light" | "dark";',
    "",
    "/**",
    " * One entry of the palette library. `mode` is the resolved theme a palette",
    " * belongs to; `swatch` holds the four hexes the picker paints, already",
    " * composited so a translucent screen tone is a real colour.",
    " */",
    "export type Palette = {",
    "  readonly id: string;",
    "  readonly name: string;",
    '  readonly mode: "light" | "dark";',
    "  readonly swatch: {",
    "    readonly base: string;",
    "    readonly background: string;",
    "    readonly ink: string;",
    "    readonly accent: string;",
    "  };",
    "};",
    "",
    "/**",
    " * Every palette, in picker order: the two authored Houston sets, then the",
    " * imported light palettes, then the dark ones. An imported palette is worn by",
    ' * setting data-palette="<id>" alongside the resolved data-theme.',
    " */",
    `export const palettes = ${paletteList(palettes)} as const satisfies readonly Palette[];`,
    "",
    'export type PaletteId = (typeof palettes)[number]["id"];',
    "",
    "/** Semantic colours, keyed by the same names as the --ht-* CSS variables. */",
    `export const color = {\n  light: ${strLit(colors(light), "    ")},\n  dark: ${strLit(
      colors(dark),
      "    ",
    )},\n} as const;`,
    "",
    `export const space = ${strLit(scale(light, "space"))} as const;`,
    "",
    `export const radius = ${strLit(scale(light, "radius"))} as const;`,
    "",
    "/** Responsive boundaries as CSS dimension strings (media-query authoring). */",
    `export const breakpoint = ${strLit(scale(light, "breakpoint"))} as const;`,
    "",
    "/** Responsive boundaries as unitless px, for JS width comparisons. */",
    `export const breakpointPx = ${lit(scale(light, "breakpoint").map((e) => [e.name, String(px(e.value))]))} as const;`,
    "",
    `export const fontFamily = ${strLit(font(light, "family"))} as const;`,
    "",
    `export const fontWeight = ${lit(font(light, "weight").map((e) => [e.name, String(e.value)]))} as const;`,
    "",
    `export const fontSize = ${strLit(font(light, "size"))} as const;`,
    "",
    "/** CSS duration strings (e.g. transition/animation shorthands). */",
    `export const duration = ${strLit(durations)} as const;`,
    "",
    "/** Durations in milliseconds, for JS-driven animation. */",
    `export const durationMs = ${lit(durations.map((e) => [e.name, String(durationMs(e.value))]))} as const;`,
    "",
    "/** Cubic-bezier control points [x1, y1, x2, y2]. */",
    `export const easing = ${lit(easings(light).map((e) => [e.name, `[${e.value.join(", ")}]`]))} as const;`,
    "",
    "/** Elevation tiers as ready-to-use CSS box-shadow strings, per theme. */",
    `export const shadow = {\n  light: ${boxShadows(light, "    ")},\n  dark: ${boxShadows(
      dark,
      "    ",
    )},\n} as const;`,
    "",
  ];
  return parts.join("\n");
}
